mapper.select:
SELECT pb.pb_id pbId, pb.factor_type factorType, pb.prd_portfolio_id prdPortfolioId, (CASE WHEN pb.factor_type ='0' THEN fin.finprod_name ELSE ptl.portfolio_name END) prdPortfolioName, pb.update_time updateTime, pb.update_user updateUser, pb.seqno FROM TRD_PB_RELATION pb LEFT JOIN ptl_portfolio ptl ON pb.prd_portfolio_id=ptl.portfolio_id LEFT JOIN FIN_PRODUCT fin ON pb.prd_portfolio_id=fin.FINPROD_ID AND fin.finprod_type2 = 'F16' WHERE 1=1
and pb.prd_portfolio_id = #{prdPortfolioId,jdbcType=VARCHAR}
and pb.pb_id = #{pbId,jdbcType=VARCHAR}
and pb.seqno = #{seqno,jdbcType=VARCHAR}
ORDER BY pb.update_time
